use std::collections::HashMap;use crate::ast::{Program,Statement};use crate::{Attention,Edge,EpistemicGraph,NodeId,NodeKind,Relation,StopReason};
#[derive(Debug,Clone,PartialEq,Eq)]pub struct ResourceLedger{pub initial:u64,pub remaining:u64,pub spent:u64,pub exhausted:bool}
#[derive(Debug,Clone,PartialEq,Eq)]pub struct EpistemicSnapshot{pub nodes:HashMap<NodeId,NodeKind>,pub edges:Vec<Edge>,pub resources:Option<ResourceLedger>}
#[derive(Debug,Clone,PartialEq,Eq)]pub struct InferenceRule{pub premises:Vec<NodeId>,pub conclusion:NodeId}
#[derive(Debug,Clone,PartialEq,Eq)]pub enum EventKind{BudgetDeclared{units:u64},Examined{caveat:NodeId,cost:u64,remaining:u64},Inferred{rule:String,conclusion:NodeId,premises:Vec<NodeId>},Committed{commitment:NodeId,retained:Vec<NodeId>,reason:StopReason,snapshot:EpistemicSnapshot},Reopened{commitment:NodeId,because:NodeId}}
#[derive(Debug,Clone,PartialEq,Eq)]pub struct Event{pub sequence:u64,pub kind:EventKind}
#[derive(Debug)]pub struct Evaluation{pub graph:EpistemicGraph,pub symbols:HashMap<String,NodeId>,pub resources:Option<ResourceLedger>,pub history:Vec<Event>,pub rules:HashMap<String,InferenceRule>}
pub fn evaluate(program:&Program)->Result<Evaluation,String>{let mut g=EpistemicGraph::new();let mut sy=HashMap::new();let mut res=None;let mut history=vec![];let mut rules=HashMap::new();let mut seq=1;macro_rules! event{($k:expr)=>{{history.push(Event{sequence:seq,kind:$k});seq+=1;}}}
for st in &program.statements{match st{
Statement::Budget{units}=>{if res.is_some(){return Err("budget already defined".into())}res=Some(ResourceLedger{initial:*units,remaining:*units,spent:0,exhausted:*units==0});event!(EventKind::BudgetDeclared{units:*units});}
Statement::Claim{name}=>{let i=g.add(NodeKind::Claim{proposition:name.clone()});define(&mut sy,name,i)?}
Statement::Evidence{name,source}=>{let i=g.add(NodeKind::Evidence{description:name.clone(),source:source.clone()});define(&mut sy,name,i)?}
Statement::Caveat{name,consequence}=>{let i=g.add_caveat(name,*consequence);define(&mut sy,name,i)?}
Statement::Relate{from,relation,to}=>g.relate(resolve(&sy,from)?,*relation,resolve(&sy,to)?),
Statement::Attention{caveat,state}=>g.set_attention(resolve(&sy,caveat)?,*state),
Statement::Examine{caveat,cost}=>{let i=resolve(&sy,caveat)?;let r=res.as_mut().ok_or("examine cost requires a budget")?;if *cost>r.remaining{return Err(format!("insufficient budget: examination of {caveat} costs {cost}, remaining {}",r.remaining))}r.remaining-=*cost;r.spent+=*cost;r.exhausted=r.remaining==0;let remaining=r.remaining;g.set_attention(i,Attention::Examined);event!(EventKind::Examined{caveat:i,cost:*cost,remaining});}
Statement::Rule{name,premises,conclusion}=>{if rules.contains_key(name){return Err(format!("duplicate rule: {name}"))}let ps=premises.iter().map(|n|resolve(&sy,n)).collect::<Result<Vec<_>,_>>()?;let c=resolve(&sy,conclusion)?;rules.insert(name.clone(),InferenceRule{premises:ps,conclusion:c});}
Statement::Infer{rule}=>{let r=rules.get(rule).ok_or_else(||format!("unknown rule: {rule}"))?.clone();for p in &r.premises{g.relate(*p,Relation::Supports,r.conclusion)}event!(EventKind::Inferred{rule:rule.clone(),conclusion:r.conclusion,premises:r.premises});}
Statement::Commit{action,reason,retaining}=>{if matches!(reason,StopReason::BudgetExhausted)&&!res.as_ref().map(|r|r.exhausted).unwrap_or(false){return Err("budget commitment requires exhausted budget".into())}let ids=retaining.iter().map(|n|resolve(&sy,n)).collect::<Result<Vec<_>,_>>()?;let i=g.commit_because(action,&ids,reason.clone());define(&mut sy,action,i)?;let snapshot=EpistemicSnapshot{nodes:g.nodes.clone(),edges:g.edges.clone(),resources:res.clone()};event!(EventKind::Committed{commitment:i,retained:ids,reason:reason.clone(),snapshot});}
Statement::Reopen{commitment,because}=>{let c=resolve(&sy,commitment)?;let b=resolve(&sy,because)?;g.reopen(c,b);event!(EventKind::Reopened{commitment:c,because:b});}
}}let _=seq;Ok(Evaluation{graph:g,symbols:sy,resources:res,history,rules})}
fn define(s:&mut HashMap<String,NodeId>,n:&str,i:NodeId)->Result<(),String>{if s.insert(n.into(),i).is_some(){Err(format!("duplicate symbol: {n}"))}else{Ok(())}}fn resolve(s:&HashMap<String,NodeId>,n:&str)->Result<NodeId,String>{s.get(n).copied().ok_or_else(||format!("unknown symbol: {n}"))}
#[cfg(test)]mod tests{use super::*;#[test]fn inference_is_local_not_explosive(){let p=crate::parser::parse("claim p; claim not_p; claim q; claim unrelated; evidence ep from s1; evidence en from s2; ep supports p; en supports not_p; rule rq when p => q; infer rq;").unwrap();let e=evaluate(&p).unwrap();let q=e.symbols["q"];let unrelated=e.symbols["unrelated"];assert!(e.graph.edges.iter().any(|x|x.to==q&&x.relation==Relation::Supports));assert!(!e.graph.edges.iter().any(|x|x.to==unrelated&&x.relation==Relation::Supports));}
#[test]fn inference_event_preserves_premises(){let p=crate::parser::parse("claim a; claim b; claim c; rule r when a, b => c; infer r;").unwrap();let e=evaluate(&p).unwrap();assert!(e.history.iter().any(|x|matches!(&x.kind,EventKind::Inferred{rule,premises,..}if rule=="r"&&premises.len()==2)));}}
